selector_to_html = {"a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u7528\u6237\u6307\u5357<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 Hints\u3001TLE-Lite\u3001TLE-Struct \u548c TLE-Raw \u7f16\u8bd1\u5668\u8bed\u8a00\u6765\u4f18\u5316\u7f16\u8bd1\u3002\u5173\u4e8e\u5982\u4f55\u5728 Hints\u3001TLE-Lite\u3001TLE-Struct \u548c TLE-Raw \u4e4b\u95f4\u8fdb\u884c\u9009\u62e9\uff0c\u5efa\u8bae\u60a8\u5148\u9605\u8bfb <a class=\"reference internal\" href=\"../FlagTree_overview/FlagTree-overview.html\"><span class=\"std std-doc\">FlagTree \u6982\u8ff0</span></a>\u3002</p>", "a[href=\"use-tle-lite.html#local-ptr\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0e local_ptr \u4ea4\u4e92\u7684\u539f\u8bed<a class=\"headerlink\" href=\"#local-ptr\" title=\"Link to this heading\">#</a></h2><p>\u4ee5\u4e0b API \u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.local_ptr</span></code> \u4e00\u8d77\u4f7f\u7528\u3002\u66f4\u591a\u4fe1\u606f\u8bf7\u53c2\u89c1 <a class=\"reference internal\" href=\"use-tle-struct.html\"><span class=\"std std-doc\">\u4f7f\u7528 TLE-Struct</span></a>\u3002</p>", "a[href=\"use-tle-struct.html#id6\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5207\u7247\u548c\u89c6\u56fe<a class=\"headerlink\" href=\"#id6\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.extract_slice\u3001tle.dsa.insert_slice\u3001tle.dsa.extract_element \u548c tle.dsa.subview<a class=\"headerlink\" href=\"#tle-dsa-extract-slicetle-dsa-insert-slicetle-dsa-extract-element-tle-dsa-subview\" title=\"Link to this heading\">#</a></h3><p>\u5207\u7247\u548c\u89c6\u56fe API \u5305\u62ec:</p>", "a[href=\"examples.html#mla\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7a00\u758f MLA \u524d\u5411\u4f20\u64ad<a class=\"headerlink\" href=\"#mla\" title=\"Link to this heading\">#</a></h2><p>\u672c\u6a21\u5757\u5b9e\u73b0\u4e86\u4e00\u4e2a\u7528\u4e8e\u7a00\u758f MLA\uff08\u591a\u5934\u6ce8\u610f\u529b\uff09\u673a\u5236\u524d\u5411\u4f20\u64ad\u7684 Triton \u5185\u6838\u3002\u5b83\u6f14\u793a\u4e86\u5982\u4f55\u4f7f\u7528 <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.load</span></code> \u5b9e\u73b0\u9ad8\u6548\u7684\u5185\u5b58\u8bbf\u95ee\u548c\u8ba1\u7b97\u3002</p>", "a[href=\"use-tle-struct.html#gpu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">GPU \u5185\u5b58\u7ba1\u7406<a class=\"headerlink\" href=\"#gpu\" title=\"Link to this heading\">#</a></h2><p>\u60a8\u53ef\u4ee5\u4f7f\u7528\u4ee5\u4e0b\u64cd\u4f5c\u6765\u7ba1\u7406 GPU \u7684\u5185\u5b58\u3002</p>", "a[href=\"../FlagTree_overview/FlagTree-overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagTree \u6982\u8ff0<a class=\"headerlink\" href=\"#flagtree\" title=\"Link to this heading\">#</a></h1><p>FlagTree \u662f\u4e00\u4e2a\u9762\u5411\u591a\u79cd AI \u82af\u7247\u7684\u5f00\u6e90\u7edf\u4e00\u7f16\u8bd1\u5668\u3002FlagTree \u81f4\u529b\u4e8e\u4e3a\u591a\u6837\u5316\u7684 AI \u82af\u7247\u6784\u5efa\u7f16\u8bd1\u5668\u53ca\u76f8\u5173\u5de5\u5177\u5e73\u53f0\uff0c\u63a8\u8fdb\u548c\u6269\u5c55 Triton \u4e0a\u4e0b\u6e38\u751f\u6001\u7cfb\u7edf\uff0c\u76ee\u6807\u662f\u652f\u6301\u73b0\u6709\u9002\u914d\u65b9\u6848\u3001\u7edf\u4e00\u4ee3\u7801\u4ed3\u5e93\uff0c\u5e76\u4ece\u5355\u4e00\u4ed3\u5e93\u5b9e\u73b0\u5feb\u901f\u7684\u591a\u540e\u7aef\u652f\u6301\u3002\u5bf9\u4e8e\u4e0a\u6e38\u6a21\u578b\u7528\u6237\uff0cFlagTree \u63d0\u4f9b\u8de8\u591a\u4e2a\u540e\u7aef\u7684\u7edf\u4e00\u7f16\u8bd1\u652f\u6301\uff1b\u5bf9\u4e8e\u4e0b\u6e38\u82af\u7247\u5382\u5546\uff0cFlagTree \u63d0\u4f9b\u96c6\u6210\u5230 Triton \u751f\u6001\u7cfb\u7edf\u7684\u53c2\u8003\u5b9e\u73b0\u3002</p>", "a[href=\"use-hints.html#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u652f\u6301\u7684\u63d0\u793a<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>\u4e0b\u8868\u5217\u51fa\u4e86\u5728\u4e0d\u540c\u540e\u7aef\u4e0a\u7f16\u8bd1\u65f6\u9002\u7528\u4e8e Triton \u64cd\u4f5c\u7684\u4f18\u5316\u63d0\u793a\u3002</p>", "a[href=\"use-tle-lite.html#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u626b\u63cf\u548c\u6392\u5e8f\u64cd\u4f5c<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u626b\u63cf\u548c\u6392\u5e8f\u64cd\u4f5c\u63d0\u4f9b\u4e86\u90e8\u5206\u5f20\u91cf\u539f\u8bed\uff0c\u5982\u524d\u7f00\u3001\u6392\u540d\u548c\u9009\u62e9\uff0c\u9002\u7528\u4e8e\u57fa\u4e8e\u76f4\u65b9\u56fe\u7684 top-k\u3001\u6d41\u538b\u7f29\u4ee5\u53ca\u5757\u7ea7\u6392\u5e8f\u548c\u5206\u6876\u573a\u666f\u3002</p><p>TLE-Lite \u5c06\u8fd9\u4e9b\u64cd\u4f5c\u4fdd\u6301\u4e3a\u9ad8\u7ea7\u8bed\u4e49\uff0c\u800c\u4e0d\u662f\u5c06\u5176\u7ed1\u5b9a\u5230\u7279\u5b9a\u7684\u786c\u4ef6\u5b9e\u73b0\uff1a\u7528\u6237\u63cf\u8ff0\u626b\u63cf\u548c\u6392\u5e8f\u610f\u56fe\uff0c\u540e\u7aef\u6839\u636e\u786c\u4ef6\u9009\u62e9\u5bc4\u5b58\u5668\u6216\u5171\u4eab\u5185\u5b58\u7684\u4e0b\u5c42\u7b56\u7565\u3002</p>", "a[href=\"use-tle-struct.html#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5411\u91cf\u8fd0\u7b97\u7b26\uff08\u7f13\u51b2\u533a\u5f62\u5f0f\uff09<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.add\u3001tle.dsa.sub\u3001tle.dsa.mul\u3001tle.dsa.div\u3001tle.dsa.max \u548c tle.dsa.min<a class=\"headerlink\" href=\"#tle-dsa-addtle-dsa-subtle-dsa-multle-dsa-divtle-dsa-max-tle-dsa-min\" title=\"Link to this heading\">#</a></h3><p>\u5185\u7f6e\u8fd0\u7b97\u7b26:\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.add</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.sub</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.mul</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.div</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.max</span></code>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.min</span></code></p><p>\u901a\u7528\u7b7e\u540d:<br/>\n<code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.(lhs,</span> <span class=\"pre\">rhs,</span> <span class=\"pre\">out)</span></code></p>", "a[href=\"use-tle-lite.html#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6d41\u6c34\u7ebf<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><h3>\u7ba1\u9053\u4e0e\u9636\u6bb5<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.pipe</span></code> \u63cf\u8ff0\u4e86\u751f\u4ea7\u8005\u4e0e\u4e00\u4e2a\u6216\u591a\u4e2a\u6d88\u8d39\u8005\u4e4b\u95f4\u7684\u663e\u5f0f\u6570\u636e\u6d41\u8fb9\u3002\u5b83\u540c\u65f6\u8bb0\u5f55\u6301\u6709\u903b\u8f91\u5757\u7684\u5171\u4eab\u5185\u5b58\u9636\u6bb5\u4ee5\u53ca\u4f7f\u8be5\u5757\u5bf9\u6d88\u8d39\u8005\u53ef\u89c1\u6240\u9700\u7684\u540c\u6b65\uff0c\u4f7f\u5f97 CTA \u7ea7\u522b\u7684\u52a0\u8f7d/\u8ba1\u7b97\u91cd\u53e0\u548c warp \u4e13\u7528\u7684\u751f\u4ea7\u8005/\u6d88\u8d39\u8005\u4ee3\u7801\u80fd\u591f\u4f7f\u7528\u7c7b\u578b\u5316\u63cf\u8ff0\u7b26\uff0c\u800c\u4e0d\u662f\u624b\u52a8\u7f16\u5199\u591a\u4e2a\u5c4f\u969c\u3002</p>", "a[href=\"use-tle-struct.html#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6267\u884c\u7f16\u6392<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><h3>tle.gpu.warp_specialize<a class=\"headerlink\" href=\"#tle-gpu-warp-specialize\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.warp_specialize</span></code> \u7528\u4e8e\u5728\u540c\u4e00 CTA \u5185\u663e\u5f0f\u521b\u5efa warp \u4e13\u7528\u533a\u57df\uff0c\u5c06\u4e0d\u540c\u7684 JIT \u51fd\u6570\u653e\u5165\u4e0d\u540c\u7684 warp \u5206\u533a\u3002\u5178\u578b\u7528\u4f8b\u662f\u5c06 TMA/cp.async \u751f\u4ea7\u8005\u3001WGMMA \u6d88\u8d39\u8005\u548c epilogue/reduction \u7b49\u4efb\u52a1\u5206\u79bb\uff0c\u5e76\u901a\u8fc7 <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.pipe</span></code> \u6216\u5176\u4ed6\u663e\u5f0f\u540c\u6b65\u539f\u8bed\u5728\u5b83\u4eec\u4e4b\u95f4\u4f20\u9012\u5171\u4eab\u5185\u5b58\u6570\u636e\u3002</p>", "a[href=\"use-tle-raw.html#mlir-llvm\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5c06 MLIR \u65b9\u8a00\u96c6\u6210\u5230 LLVM \u4e2d\u4ee5\u5b9e\u73b0\u53ef\u79fb\u690d\u6027\u548c\u53ef\u7ec4\u5408\u4f18\u5316<a class=\"headerlink\" href=\"#mlir-llvm\" title=\"Link to this heading\">#</a></h2><p>\u4ee5\u4e0b\u662f MLIR\uff08\u591a\u7ea7\u4e2d\u95f4\u8868\u793a\uff09\u7684\u793a\u4f8b\u3002</p>", "a[href=\"use-tle-lite.html#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5f20\u91cf\u5207\u7247<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2><p>\u6839\u636e\u6307\u5b9a\u7684\u5b50\u5207\u7247\u5f62\u72b6\u5c06\u8f93\u5165\u5f20\u91cf\u5206\u5272\u4e3a\u5b50\u5207\u7247\u7f51\u683c\uff0c\u5e76\u63d0\u53d6\u7ed9\u5b9a\u5750\u6807\u5904\u7684\u5b50\u5207\u7247\u3002\nGPU\uff1a\u652f\u6301\u63d0\u53d6\u5230\u5bc4\u5b58\u5668\u548c\u5171\u4eab\u5185\u5b58\u4e2d\u3002</p>", "a[href=\"use-tle-raw.html#cuda-llvm\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5c06 CUDA \u96c6\u6210\u5230 LLVM \u4e2d\u4ee5\u5b9e\u73b0\u6700\u5927\u7ec6\u7c92\u5ea6\u63a7\u5236<a class=\"headerlink\" href=\"#cuda-llvm\" title=\"Link to this heading\">#</a></h2><p>\u672c\u8282\u4ec5\u4ecb\u7ecd\u5982\u4f55\u5c06 CUDA \u5185\u6838\u96c6\u6210\u5230 LLVM \u5185\u8054\u8def\u5f84\u4e2d\u3002\u5c06\u5176\u4ed6\u5382\u5546\u96c6\u6210\u5230 LLVM \u5185\u8054\u8def\u5f84\u4e2d\u53ef\u4ee5\u9075\u5faa\u7c7b\u4f3c\u7684\u6b65\u9aa4\u3002</p><p>TLE-Raw \u901a\u8fc7 LLVM \u5185\u8054\u8def\u5f84\u652f\u6301 CUDA \u5185\u6838\u96c6\u6210\u3002\u5728 CUDA \u4fa7\u96c6\u6210 TLE-Raw \u7684\u5382\u5546\u5e94\u8bc4\u4f30\uff1a</p>", "a[href=\"use-hints.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 Hints<a class=\"headerlink\" href=\"#hints\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree_hints</span></code> \u5141\u8bb8\u7528\u6237\u901a\u8fc7 Triton Kernel \u4ee3\u7801\u4e2d\u7684\u884c\u5c3e\u6ce8\u91ca\u5411\u7f16\u8bd1\u5668\u63d0\u4f9b\u4f18\u5316\u63d0\u793a\u3002</p><p>\u4f60\u53ef\u4ee5\u7b80\u5355\u5730\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">tl.load</span></code> \u7b49\u64cd\u4f5c\u6240\u5728\u7684\u540c\u4e00\u884c\u6dfb\u52a0\u683c\u5f0f\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">#</span> <span class=\"pre\">@hint:</span> <span class=\"pre\">&lt;hint_name&gt;</span></code> \u7684\u884c\u5c3e\u6ce8\u91ca\u6765\u6dfb\u52a0\u63d0\u793a\u3002</p>", "a[href=\"examples.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u793a\u4f8b<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u5305\u542b FlagTree \u793a\u4f8b\u3002</p>", "a[href=\"use-tle-cpu.html#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u67b6\u6784\u6982\u89c8<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2>", "a[href=\"use-tle-lite.html#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5185\u5b58\u7ba1\u7406<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>\u60a8\u53ef\u4ee5\u4f7f\u7528\u4ee5\u4e0b\u64cd\u4f5c\u6765\u7ba1\u7406\u5185\u5b58\u3002</p>", "a[href=\"use-tle-struct.html#dsa\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">DSA \u5185\u5b58\u7ba1\u7406\u548c\u6570\u636e\u79fb\u52a8<a class=\"headerlink\" href=\"#dsa\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.alloc<a class=\"headerlink\" href=\"#tle-dsa-alloc\" title=\"Link to this heading\">#</a></h3><p>\u7b7e\u540d: <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.dsa.alloc(shape,</span> <span class=\"pre\">dtype,</span> <span class=\"pre\">mem_addr_space)</span></code>\n\u7528\u9014: \u5728\u6307\u5b9a\u7684\u5185\u5b58\u5730\u5740\u7a7a\u95f4\u4e2d\u5206\u914d DSA \u672c\u5730\u7f13\u51b2\u533a\u3002\n\u534e\u4e3a Ascend \u66b4\u9732\u7684\u5730\u5740\u7a7a\u95f4:</p>", "a[href=\"use-tle-cpu.html#arm64-cpu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Arm64 CPU \u76f8\u5173\u94fe\u63a5<a class=\"headerlink\" href=\"#arm64-cpu\" title=\"Link to this heading\">#</a></h2><p>\u4ee5\u4e0b\u662f TLE-CPU \u548c Arm64 \u7684\u76f8\u5173\u94fe\u63a5\uff1a</p>", "a[href=\"use-tle-raw.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-Raw<a class=\"headerlink\" href=\"#tle-raw\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-Raw\u3002TLE-Raw \u5728 trition_3.6.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p><p>TLE Raw \u4e3a Triton \u63d0\u4f9b\u4e86\u4f4e\u7ea7\u6269\u5c55\u63a5\u53e3\uff0c\u5141\u8bb8\u7528\u6237\u901a\u8fc7\u7b2c\u4e09\u65b9\u65b9\u8a00\u548c\u8bed\u8a00\uff08\u4f8b\u5982\u4f7f\u7528 CUDA \u8fdb\u884c\u7ebf\u7a0b\u7ea7\u8c03\u5ea6\u3001\u540c\u6b65\u548c\u5185\u5b58\u8bbf\u95ee\uff09\u6765\u586b\u8865\u80fd\u529b\u7a7a\u767d\u5e76\u83b7\u5f97\u7ec6\u7c92\u5ea6\u63a7\u5236\u3002\u7528\u6237\u53ef\u4ee5\u6839\u636e\u76ee\u6807\u786c\u4ef6\u548c\u5de5\u5177\u94fe\u6210\u719f\u5ea6\uff0c\u5728\u53ef\u79fb\u690d\u6027\u548c\u53ef\u7ec4\u5408\u4f18\u5316\uff08\u901a\u8fc7 MLIR \u65b9\u8a00\u96c6\u6210\uff09\u4e0e\u6700\u5927\u7ec6\u7c92\u5ea6\u63a7\u5236\uff08\u901a\u8fc7 CUDA \u96c6\u6210\uff09\u4e4b\u95f4\u8fdb\u884c\u9009\u62e9\u3002</p>", "a[href=\"use-tle-struct.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-Struct<a class=\"headerlink\" href=\"#tle-struct\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-Struct\u3002TLE-Struct \u5728 trition_3.6.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p>", "a[href=\"use-tle-cpu.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-CPU<a class=\"headerlink\" href=\"#tle-cpu\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-CPU\u3002TLE-CPU \u5728 trition_3.3.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p><p>TLE-CPU \u63d0\u4f9b\u7edf\u4e00\u7684\u7f16\u7a0b\u8303\u5f0f\uff0c\u8986\u76d6\u591a\u6837\u5316\u7684\u8fb9\u7f18\u7aef CPU \u7b97\u529b\u3002\u5c06 TLE \u201c\u5728 <code class=\"docutils literal notranslate\"><span class=\"pre\">@triton.jit</span></code> \u4e4b\u4e0a\u5206\u5c42\u786c\u4ef6\u6df1\u5ea6\u4f18\u5316\u201d\u7684\u7406\u5ff5\u6269\u5c55\u5230 CPU\u3002\u9488\u5bf9\u8fb9\u7f18 AI \u788e\u7247\u5316\u7684 CPU \u751f\u6001\uff08Arm64 / RISC-V / x86\uff0c\u591a\u79cd ISA \u5e76\u5b58\uff09\uff0c\u4f7f\u7528\u76f8\u540c\u7684 Triton \u7f16\u7a0b\u6a21\u578b\u548c\u96c6\u6210\u6846\u67b6\u6765\u652f\u6301\u4e0d\u540c\u7684 ISA\uff1a\u7f16\u7a0b\u6a21\u578b\u548c\u6b63\u786e\u6027\u8de8 ISA \u5171\u4eab\uff08\u666e\u901a Triton \u901a\u8fc7 LLVM \u843d\u5230\u4efb\u610f ISA\uff09\uff0c\u800c\u6bcf\u4e2a ISA \u7684\u9ad8\u6027\u80fd\u5b9e\u73b0\uff08intrinsic / C \u8fd0\u884c\u65f6\uff09\u5219\u5206\u522b\u8d21\u732e\u3002\u6a21\u578b\u4ee3\u7801\u901a\u8fc7\u7b97\u5b50\u5e93\uff08FlagGems\uff09\u7684 vendor \u5206\u53d1\u8def\u7531\u5230\u5bf9\u5e94\u7684 ISA \u5b9e\u73b0\uff0c\u65e0\u9700\u611f\u77e5\u5177\u4f53 ISA\u3002CPU \u4e0e GPU \u7684\u5dee\u5f02\u51b3\u5b9a\u4e86\u5b83\u9700\u8981\u4e00\u4e2a\u72ec\u7acb\u7684\u6269\u5c55\u9762\uff1a</p>", "a[href=\"use-tle-struct.html#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5faa\u73af\u548c\u63d0\u793a<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><h3>tle.dsa.pipeline\u3001tle.dsa.parallel \u548c tle.dsa.hint<a class=\"headerlink\" href=\"#tle-dsa-pipelinetle-dsa-parallel-tle-dsa-hint\" title=\"Link to this heading\">#</a></h3><p>\u5faa\u73af\u548c\u63d0\u793a API \u5305\u62ec:</p>", "a[href=\"use-tle-lite.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-Lite<a class=\"headerlink\" href=\"#tle-lite\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-Lite\u3002TLE-Lite \u5728 trition_3.6.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p>", "a[href=\"use-tle-cpu.html#cpu\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u652f\u6301\u7684 CPU \u67b6\u6784<a class=\"headerlink\" href=\"#cpu\" title=\"Link to this heading\">#</a></h2>", "a[href=\"use-tle-lite.html#id11\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u5206\u5e03\u5f0f<a class=\"headerlink\" href=\"#id11\" title=\"Link to this heading\">#</a></h2><p>Triton \u5206\u5e03\u5f0f API \u7531\u56db\u4e2a\u6838\u5fc3\u90e8\u5206\u7ec4\u6210\uff1a\u8bbe\u5907\u7f51\u683c\u5b9a\u4e49\u3001\u5206\u7247\u89c4\u8303\u63cf\u8ff0\u3001\u540c\u6b65\u548c\u8fdc\u7a0b\u8bbf\u95ee\uff08\u70b9\u5bf9\u70b9\u901a\u4fe1\uff09\u3002</p><p>\u8de8\u5361/\u8de8\u8282\u70b9\u7684\u5e95\u5c42\u901a\u4fe1\u5728\u4e0d\u540c\u5c42\u7ea7\u4e0a\u63d0\u4f9b\uff1aTLE-Lite \u548c TLE-Struct \u7684\u5206\u5e03\u5f0f\u539f\u8bed\u901a\u8fc7 FlagCX \u5b8c\u6210\u8de8\u8bbe\u5907\u901a\u4fe1\uff1bTLE-Raw \u5219\u66f4\u5e95\u5c42\uff0c\u4e0e Raw \u5904\u4e8e\u540c\u4e00\u7ea7\u522b\uff0c\u901a\u8fc7 NVSHMEM \u76f4\u63a5\u63d0\u4f9b\u8bbe\u5907\u7aef\u901a\u4fe1\u63a5\u53e3\uff08\u89c1<a class=\"reference internal\" href=\"use-tle-raw.html\"><span class=\"std std-doc\">\u4f7f\u7528 TLE-Raw</span></a>\uff09\uff0c\u4e14 NVSHMEM \u4ec5\u7528\u4e8e NVIDIA \u5361\u3002</p>", "a[href=\"use-tle-struct.html#tle-gpu-barrier-api\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">tle.gpu barrier API<a class=\"headerlink\" href=\"#tle-gpu-barrier-api\" title=\"Link to this heading\">#</a></h2><p>TLE GPU barrier \u7528\u4e8e\u8868\u8fbe\u624b\u5199 Hopper producer/consumer \u6d41\u6c34\u6240\u9700\u7684\u540c\u6b65\uff0c\u5305\u62ec TMA completion barrier\u3001empty/full mbarrier\uff0c\u4ee5\u53ca warp group \u4e4b\u95f4\u7684\u8f7b\u91cf named barrier\u3002</p><p>API \u603b\u89c8\uff1a</p>"}
